package dev.kubejseditor.client;

import com.google.gson.*;
import dev.kubejseditor.recipe.compat.*;
import dev.kubejseditor.runtime.*;
import dev.kubejseditor.storage.ProjectStore;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.components.*;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.network.chat.Component;
import java.util.*;
import java.util.function.Consumer;
import static dev.kubejseditor.recipe.compat.CompatDefinition.*;

/** Confirmation is explicit: a JSON shape alone never assigns an input/output meaning. */
public final class CompatMappingScreen extends Screen {
    private final Screen parent;private final JsonObject data;private final Consumer<CompatDefinition> accepted;private CompatDefinition definition;private int offset;private boolean advanced=CompatUiPreferences.advanced(),resetPending;private String errorDetails="";private String status="选择字段后确认用途；清空可取消映射，重置可恢复自动识别。";
    public CompatMappingScreen(Screen parent,JsonObject data,CompatDefinition initial,Consumer<CompatDefinition> accepted){super(Component.literal("通用配方 · 确认字段映射"));this.parent=parent;this.data=data;this.accepted=accepted;definition=initial==null?new CompatDefinition(data.get("type").getAsString(),"confirmed"):ProjectStore.JSON.fromJson(ProjectStore.JSON.toJson(initial),CompatDefinition.class);}
    private void button(String text,int x,int y,int w,Runnable action){addRenderableWidget(Button.builder(Component.literal(text),b->{try{action.run();}catch(Exception e){status=e.getMessage();}}).bounds(x,y,w,20).build());}
    @Override protected void init(){button("+ 选择字段",16,36,120,this::pickPath);button(advanced?"模式：高级":"模式：初级",142,36,114,()->{advanced=!advanced;CompatUiPreferences.advanced(advanced);offset=0;rebuildWidgets();});button("清空映射",16,62,104,this::clear);button("重置映射",124,62,104,this::reset);if(advanced)button("映射 JSON",232,62,Math.max(64,Math.min(120,width-248)),()->minecraft.setScreen(new CompatValueScreen(this,"高级字段定义",ProjectStore.JSON.toJson(definition),text->{var d=ProjectStore.JSON.fromJson(text,CompatDefinition.class);if(!definition.type.equals(d.type))throw new IllegalArgumentException("不能更换原生类型");d.check();definition=d;manual();})));
        int rows=Math.max(1,(height-172)/38);offset=Math.min(offset,Math.max(0,definition.fields.size()-rows));for(int i=offset;i<Math.min(definition.fields.size(),offset+rows);i++){var f=definition.fields.get(i);int y=94+(i-offset)*38;String label=CompatLabels.name(f)+" · "+(advanced?f.role+" / "+f.kind+" · "+f.path:CompatFields.basicRole(f));button(font.plainSubstrByWidth(label,width-102),16,y,width-70,()->{if(advanced)fieldOptions(f);else basicRoles(f,CompatJson.get(data,f.path));});button("×",width-46,y,30,()->{definition.fields.remove(f);manual();rebuildWidgets();});}
        button("确认并保存映射",16,height-30,142,()->{try{if(resetPending)CompatibilityRecipes.reset(definition,data);else CompatibilityRecipes.confirm(definition,data,parent instanceof CompatibilityScreen screen&&screen.draft.forceNative);accepted.accept(definition);minecraft.setScreen(parent);}catch(Exception e){status="错误："+e.getMessage();errorDetails=definition.type+"\n"+e+"\n\n"+ProjectStore.JSON.toJson(definition);CompatDiagnostics.failure("mapping-confirm",definition.type,e);rebuildWidgets();}});if(!errorDetails.isBlank())button("错误详情",166,height-30,80,()->minecraft.setScreen(new TextScreen(this,"字段确认失败 · 完整原因",errorDetails)));button("取消",width-96,height-30,80,this::onClose);}
    private void collect(JsonElement value,String path,Map<String,JsonElement> out,int depth){if(depth>8||out.size()>512)return;if(!path.isEmpty())out.put(path,value);if(value.isJsonObject()){for(var e:value.getAsJsonObject().entrySet())if(!Set.of("type","components","neoforge:conditions").contains(e.getKey()))collect(e.getValue(),path+"/"+CompatJson.escape(e.getKey()),out,depth+1);}else if(value.isJsonArray())for(int i=0;i<value.getAsJsonArray().size();i++)collect(value.getAsJsonArray().get(i),path+"/"+i,out,depth+1);}
    private void pickPath(){var paths=new LinkedHashMap<String,JsonElement>();collect(data,"",paths,0);var choices=new ArrayList<ChoiceScreen.Choice>();paths.forEach((path,value)->choices.add(new ChoiceScreen.Choice((advanced?path:path.substring(path.lastIndexOf('/')+1))+" = "+value,()->{var existing=definition.fields.stream().filter(f->f.path.equals(path)).findFirst().orElse(null);var f=existing==null?new Field(path,path,Kind.JSON,Role.PARAMETER):existing;if(advanced)pickAdvancedRole(f,value);else basicRoles(f,value);},path)));minecraft.setScreen(new ChoiceScreen(this,"选择实际字段（自动识别结果已预填）",choices));}
    private void pickAdvancedRole(Field f,JsonElement value){minecraft.setScreen(new ChoiceScreen(this,"高级字段用途",Arrays.stream(Role.values()).map(role->new ChoiceScreen.Choice(role.label(),()->{f.role=role;pickKind(f,value);})).toList()));}
    private void basicRoles(Field f,JsonElement value){var choices=new ArrayList<ChoiceScreen.Choice>();for(var role:List.of(Role.INPUT,Role.OUTPUT,Role.CATALYST,Role.PARAMETER,Role.CONDITION)){String title=switch(role){case INPUT->"输入格";case OUTPUT->"输出格";case CATALYST->"催化剂";case PARAMETER->"数值修改";default->"条件修改";};choices.add(new ChoiceScreen.Choice(title,()->{f.role=role;f.readOnlyReason="";if(role==Role.PARAMETER||role==Role.CONDITION){f.list=false;f.kind=value.isJsonPrimitive()?value.getAsJsonPrimitive().isBoolean()?Kind.BOOLEAN:value.getAsJsonPrimitive().isNumber()?Kind.NUMBER:Kind.STRING:Kind.JSON;if(role==Role.PARAMETER&&f.kind!=Kind.NUMBER){status="请选择实际数值字段；结构字段可用条件修改或高级模式";minecraft.setScreen(this);return;}put(f);minecraft.setScreen(this);}else basicKinds(f,value);}));}minecraft.setScreen(new ChoiceScreen(this,"初级：确认字段用途",choices));}
    private void basicKinds(Field f,JsonElement value){minecraft.setScreen(new ChoiceScreen(this,"格子内容类型",List.of(Kind.ITEM,Kind.FLUID,Kind.OTHER).stream().map(kind->new ChoiceScreen.Choice(kind==Kind.ITEM?"物品":kind==Kind.FLUID?"流体":"其他",()->{f.kind=kind;if(kind==Kind.OTHER){chooseOther(f,value);return;}if(value.isJsonArray()&&f.role==Role.INPUT){minecraft.setScreen(new ChoiceScreen(this,"确认原生数组的含义",List.of(new ChoiceScreen.Choice("多个输入格（每条都是独立原料）",()->{f.list=true;finishBasic(f,value);}),new ChoiceScreen.Choice("一个输入格，任意一种（OR）",()->{f.list=false;finishBasic(f,value);})))) ;}else{f.list=value.isJsonArray();finishBasic(f,value);}})).toList()));}
    private void finishBasic(Field f,JsonElement value){CompatFields.shape(f,value);put(f);var probe=new CompatDefinition(definition.type,"probe");probe.fields.add(f);var errors=new RecipePresentation(data,probe).validate();if(!errors.isEmpty())f.readOnlyReason="结构尚未完整识别，可在高级模式补充："+String.join("；",errors);minecraft.setScreen(this);}
    private void chooseOther(Field f,JsonElement value){minecraft.setScreen(new ChoiceScreen(this,"选择已注册 JEI 原料类型",CompatIngredientTypes.others().stream().map(type->new ChoiceScreen.Choice(type.getUid(),()->{f.ingredientType=type.getUid();f.list=false;try{CompatIngredientTypes.decode(f.ingredientType,value);f.readOnlyReason="";}catch(RuntimeException e){f.readOnlyReason="当前字段无法使用此类型的 Codec："+e.getMessage();}put(f);minecraft.setScreen(this);})).toList()));}
    private void manual(){resetPending=false;definition.autoDiscover=false;errorDetails="";}
    private void clear(){definition.fields.clear();manual();offset=0;status="映射已清空，确认保存后保持无映射；原始配方数据保留";rebuildWidgets();}
    private void reset(){if(!(parent instanceof CompatibilityScreen screen))throw new IllegalStateException("需要当前 JEI 页面才能重新识别");definition=screen.automaticMapping();resetPending=true;offset=0;errorDetails="";status="已重新读取自动映射，确认保存后生效";rebuildWidgets();}
    private void put(Field f){manual();definition.fields.removeIf(old->old.path.equals(f.path));definition.fields.add(f);}
    private void pickKind(Field f,JsonElement value){minecraft.setScreen(new ChoiceScreen(this,"高级字段类型",Arrays.stream(Kind.values()).map(kind->new ChoiceScreen.Choice(kind.label(),()->{f.kind=kind;f.readOnlyReason="";if(kind==Kind.OTHER){chooseOther(f,value);return;}if(!f.slot())f.list=false;put(f);minecraft.setScreen(this);fieldOptions(f);})).toList()));}
    private void fieldOptions(Field f){manual();var choices=new ArrayList<ChoiceScreen.Choice>();choices.add(new ChoiceScreen.Choice("名称 / 单位",()->minecraft.setScreen(new CompatValueScreen(this,"名称和单位：{\"label\":\"材料\",\"unit\":\"个\"}","{\"label\":"+ProjectStore.JSON.toJson(f.label)+",\"unit\":"+ProjectStore.JSON.toJson(f.unit)+"}",text->{var o=JsonParser.parseString(text).getAsJsonObject();f.label=o.get("label").getAsString();f.unit=o.get("unit").getAsString();}))));
        choices.add(new ChoiceScreen.Choice("列表："+f.list+"（关闭列表表示单个 OR 原料，需原生支持）",()->{f.list=!f.list;minecraft.setScreen(this);}));
        choices.add(new ChoiceScreen.Choice("整数："+f.integer,()->{f.integer=!f.integer;minecraft.setScreen(this);}));
        if(f.slot()){choices.add(new ChoiceScreen.Choice("数量字段："+f.quantity,()->relative(f,false)));choices.add(new ChoiceScreen.Choice("概率字段："+f.probability,()->relative(f,true)));}if(f.slot())choices.add(new ChoiceScreen.Choice("数量 / 概率 / 展开字段",()->minecraft.setScreen(new CompatValueScreen(this,"相对字段名；无该功能留空。expand 仅用于已确认的基座重复语义。","{\"quantity\":"+ProjectStore.JSON.toJson(f.quantity)+",\"probability\":"+ProjectStore.JSON.toJson(f.probability)+",\"expand\":"+ProjectStore.JSON.toJson(f.expand)+"}",text->{var o=JsonParser.parseString(text).getAsJsonObject();f.quantity=o.get("quantity").getAsString();f.probability=o.get("probability").getAsString();f.expand=o.get("expand").getAsString();}))));
        choices.add(new ChoiceScreen.Choice("查看原始值",()->minecraft.setScreen(new TextScreen(this,f.path,ProjectStore.JSON.toJson(CompatJson.get(data,f.path))))));minecraft.setScreen(new ChoiceScreen(this,"绑定设置 · "+f.path,choices));}
    private void relative(Field field,boolean probability){JsonElement value=CompatJson.get(data,field.path);if(field.list&&value.isJsonArray()&&!value.getAsJsonArray().isEmpty())value=value.getAsJsonArray().get(0);var choices=new ArrayList<ChoiceScreen.Choice>();choices.add(new ChoiceScreen.Choice("无此字段 / 固定数量",()->{if(probability)field.probability="";else field.quantity="";minecraft.setScreen(this);}));if(value.isJsonObject())for(var entry:value.getAsJsonObject().entrySet())if(entry.getValue().isJsonPrimitive()&&entry.getValue().getAsJsonPrimitive().isNumber()){String key=entry.getKey();choices.add(new ChoiceScreen.Choice(key+" = "+entry.getValue(),()->{if(probability)field.probability=key;else field.quantity=key;minecraft.setScreen(this);}));}minecraft.setScreen(new ChoiceScreen(this,probability?"确认概率字段（0～1）":"确认单条数量字段",choices));}
    @Override public void render(GuiGraphics g,int x,int y,float partial){g.fill(0,0,width,height,0xFF101923);g.drawString(font,title,16,14,0xFF7DD3FC,false);int rows=Math.max(1,(height-172)/38);for(int i=offset;i<Math.min(definition.fields.size(),offset+rows);i++){var f=definition.fields.get(i);g.drawString(font,font.plainSubstrByWidth(CompatJson.get(data,f.path).toString(),width-40),20,117+(i-offset)*38,0xFF94A3B8,false);}g.drawString(font,font.plainSubstrByWidth(status,width-32),16,height-53,0xFFFFCC88,false);super.render(g,x,y,partial);}
    @Override public boolean mouseScrolled(double x,double y,double dx,double dy){offset=Math.max(0,offset-(int)dy*3);rebuildWidgets();return true;}
    @Override public void onClose(){minecraft.setScreen(parent);}
    @Override public void renderBackground(GuiGraphics g,int x,int y,float partial){}
    @Override public boolean isPauseScreen(){return false;}
}
